#include "second_helper.hpp"
static std::vector<float> readInput(const char*p,size_t n){std::ifstream f(p,std::ios::binary|std::ios::ate);if(!f||f.tellg()!=std::streamoff(n*4))throw std::runtime_error("input size");std::vector<float>v(n);f.seekg(0);f.read((char*)v.data(),n*4);for(float x:v)if(!std::isfinite(x))throw std::runtime_error("nonfinite");return v;}
int main(int argc,char**argv){try{if(argc!=5)throw std::runtime_error("SHADERS ATLAS VERTICES OUT");auto atlas=readInput(argv[2],3185),verts=readInput(argv[3],60);for(float x:atlas)if(x<0||x>1)throw std::runtime_error("coverage");const std::array<float,16>B={.96f,0,-.28f,0,0,1,0,0,.28f,0,.96f,0,-.41f,-.125f,.38f,1};
 for(size_t i=0;i<verts.size();i+=5){if(std::abs(verts[i])>4||std::abs(verts[i+1])>4||verts[i+2]<=1.125f||verts[i+2]>=9||verts[i+3]<0||verts[i+3]>1||verts[i+4]<0||verts[i+4]>1)throw std::runtime_error("world budget");float z=B[2]*verts[i]+B[6]*verts[i+1]+B[10]*verts[i+2]+B[14];if(z<=1.125f||z>=9)throw std::runtime_error("view depth budget");}
 std::filesystem::path out=argv[4];if(!std::filesystem::create_directory(out))throw std::runtime_error("existing output");{TextLab lab(argv[1]);lab.worldBuffer=lab.buffers.size();lab.buffers.push_back(lab.buffer(verts.size()*4,VK_BUFFER_USAGE_VERTEX_BUFFER_BIT));memcpy(lab.buffers[lab.worldBuffer].map,verts.data(),verts.size()*4);
 const char*names[]={"A-depth","A-top","B-depth","B-top","B-stale-label-A"};for(int i=0;i<5;i++){bool b=i>=2,top=i==1||i==3;auto r=lab.draw(atlas,{.1f,.2f,.3f,.5f},{.9f,.5f,.2f,.75f},b?B:IDENTITY_VIEW,top,i==4);auto d=out/names[i];if(!std::filesystem::create_directory(d))throw std::runtime_error("output reuse");save(d/"color.f32",r[0]);save(d/"velocity.f32",r[1]);save(d/"id.f32",r[2]);std::vector<float>depth(3185);memcpy(depth.data(),lab.buffers[lab.readDepth].map,depth.size()*4);save(d/"depth.f32",depth);if(memcmp(lab.buffers[lab.worldBuffer].map,verts.data(),verts.size()*4))throw std::runtime_error("world vertices changed");}
 std::cout<<"SECOND_CAMERA_PASS validation_enabled="<<lab.validation<<" device_instances=1 world_vertex_buffers=1 shared_atlas_images=1 completed_draw_calls=10\n";}if(validationErrors)throw std::runtime_error("validation");return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
